from components.material_demand.work import compute


class TestMaterialDemand(unittest.TestCase):
    def test_public_fixture(self):
        payload = json.loads((ROOT / "components/material_demand/input.json").read_text())
        expected = json.loads((ROOT / "components/material_demand/expected.json").read_text())
        self.assertEqual(compute(payload), expected)

    def test_recursive_expansion_and_qty(self):
        payload = {
            "orders": [{"id": "o1", "sku": "A", "qty": 2}],
            "bom": {"A": {"B": 2}, "B": {"C": 3}},
        }
        self.assertEqual(compute(payload), {"o1": {"C": 12}})

    def test_leaf_sku_not_in_bom(self):
        payload = {
            "orders": [{"id": "o1", "sku": "X", "qty": 3}],
            "bom": {},
        }
        self.assertEqual(compute(payload), {"o1": {"X": 3}})


if __name__ == "__main__":
    unittest.main()

