                mes.append({
                    "run": run_id,
                    "line": line,
                    "seq": seq,
                    "wo": wid,
                    "qty": w["qty"],
                    "start": w["start"],
                    "end": w["end"],
                    "status": "WIP_CONT",
                })
            else:
                o = order_by_id[wid]
                l, s, e = chosen[wid]
                mes.append({
