        selected_ids, chosen, reqs = [], {}, []
    else:
        selected_ids, chosen, reqs = best

    selected = sorted(selected_ids)

    # ERP
    erp_orders = []
    for w in wip:
        erp_orders.append({
            "wo": w["id"], "run": run_id, "sku": w["sku"], "qty": w["qty"],
            "due": w["due"], "start": w["start"], "end": w["end"],
            "line": w["line"], "status": "WIP_CONT", "parent": None,
