\"], acc)\n        result[order[\"id\"]] = acc\n    return result\n", "components/material_demand/result.json": "{\"component\": \"material_demand\", \"input_sha256\": \"[HASH]\", \"value\": {\"o1\": {\"N\": 1, \"M\": 1}, \"o2\": {\"M\": 2}, \"o3\": {\"N\": 1, \"M\": 1}}}"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"components/material_demand/result.json":"[HASH]","components/material_demand/work.py":"[HASH]"},"tested_targets":[],"validated":false},{"artifact_id":"artifact-a8280e371fa90a91","branch_id":"v2-b4d9a74e0efb-1","content":"{"components/line_windows/work.py": "def compute(payload):\n    \"\"\"按工单 ID 输出合格产线及可行起止窗口三元组，按产线及起点的原遍历顺序。\"\"\"\n    orders = payload.get(\"orders\", [])\n    released = set(payload.get(\"released\", []))\n    routing = payload.get(\"routing\", {})\n    lines = payload.get(\"lines\", [])\n    wip = payload.get(\"wip\", [])\n    freeze = payload.get(\"freeze\", 0)\n    changeover = payload.get(\"changeover\", 0)\n\n    # 每条产线上所有 wip 的最大结束时间（wip 占据第一顺位）。\n    wip_end = {}\n    for w in wip:\n        line = w[\"line\"]\n        end = w[\"end\"]\n        if line not in wip_end or end > wip_end[line]:\n            wip_end[line] = end\n\n    result = {}\n    for order in orders:\n        oid = order[\"id\"]\n        sku = order[\"sku\"]\n        qty = order[\"qty\"]\n        due = order[\"due\"]\n        if sku not in released:\n            result[oid] = []\n            continue\n        r = routing.get(sku)\n        if r is None:\n            result[oid] = []\n            continue\n        duration = r[\"setup\"] + r[\"per_unit\"] * qty\n        triples = []\n        for line in lines:\n            lid = line[\"id\"]\n            if sku not in line.get(\"qualified\", []):\n                continue\n            min_start = freeze\n            if lid in wip_end:\n                min_start = max(min_start, wip_end[lid] + changeover)\n            for (ws, we) in line.get(\"windows\", []):\n                # 区间 [s