                    "status": "WIP_CONT",
                })
            else:
                o = order_by_id[wid]
                l, s, e = chosen[wid]
                mes.append({
                    "run": run_id, "line": line, "seq": seq, "wo": wid,
                    "qty": o["qty"], "start": s, "end": e, "status": "PLANNED",
                })

    # WMS
    lot_cap3 = {lot["id"]: lot["qty"] for lot in lots}
    per_order = {}
    for (oid, comp, qty, end) in reqs:
        need = qty
        for lot in usable_lots(comp, end):
            if need <= 0:
