            if take > 0:
                lot_cap3[lot["id"]] -= take
                need -= take
                per_order.setdefault(oid, []).append((comp, lot["id"], take))

    wms_rows = []
    for oid in selected_ids:
        for (comp, lot, qty) in sorted(per_order.get(oid, [])):
