    wms_rows.sort()
    for i, (oid, comp, lot, qty) in enumerate(wms_rows, start=1):
        wms.append({
            "reservation": "r%04d" % i,
            "run": run_id,
            "wo": oid,
            "component": comp,
            "lot": lot,
            "qty": qty,
            "status": "RESERVED",
        })

    return {
        "selected": selected,
        "erp": {
            "run": {"id": run_id, "freeze": freeze},
            "orders": erp_orders,
        },
        "mes": mes,
        "wms": wms,
    }


