                pass
            if wid in {w["id"] for w in wip}:
                w = next(w for w in wip if w["id"] == wid)
                mes.append({
                    "run": run_id,
                    "line": line,
                    "seq": seq,
                    "wo": wid,
                    "qty": w["qty"],
                    "start": w["start"],
                    "end": w["end"],
                    "status": "WIP_CONT",
