def diff(a,b,path=''):
    if type(a)!=type(b):
        print('TYPE',path,type(a),type(b)); return
    if isinstance(a,dict):
        for k in set(a)|set(b):
            if k not in a: print('MISSING',path+'/'+k)
            elif k not in b: print('EXTRA',path+'/'+k)
            else: diff(a[k],b[k],path+'/'+k)
