            "run": run_id,
            "wo": oid,
            "component": comp,
            "lot": lot,
            "qty": qty,
            "status": "RESERVED",
        })

    return {
        "selected": selected,
        "erp": {
            "run": {"id": run_id, "freeze": freeze},
