                        per_order.setdefault(oid, []).append((comp, lot["id"], take))

            id_list = []
            for oid in sorted(selected_ids):
                line, start, end = chosen[oid]
                a = tuple(sorted(per_order.get(oid, [])))
                id_list.append((oid, line, start, end, a))

