def diff(a,b,path=''):
    if type(a)!=type(b):
        print('TYPE',path,type(a),type(b)); return
    if isinstance(a,dict):
        for k in set(a)|set(b):
            if k not in a: print('MISSING',path+'/'+k)
            elif k not in b: print('EXTRA',path+'/'+k)
            else: diff(a[k],b[k],path+'/'+k)
    elif isinstance(a,list):
        if len(a)!=len(b): print('LEN',path,len(a),len(b))
        for i,(x,y) in enumerate(zip(a,b)): diff(x,y,path+'/'+str(i))
    else:
        if a!=b: print('VAL',path,repr(a),repr(b))
diff(r,e)
