            "wo": oid, "run": run_id, "sku": o["sku"], "qty": o["qty"],
            "due": o["due"], "start": start, "end": end,
            "line": line, "status": "PLANNED", "parent": oid,
        })
    erp_orders.sort(key=lambda x: x["wo"])

